package com.cryptosec.vault.controller;

import com.cryptosec.vault.dto.KeyResponseDto;
import com.cryptosec.vault.entity.VaultKey;
import com.cryptosec.vault.mapper.VaultKeyMapper;
import com.cryptosec.vault.repository.VaultKeyRepository;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/vault/keys")
public class KeyRetrievalController {

    private final VaultKeyRepository keyRepository;
    private final VaultKeyMapper keyMapper;

    public KeyRetrievalController(VaultKeyRepository keyRepository, VaultKeyMapper keyMapper) {
        this.keyRepository = keyRepository;
        this.keyMapper = keyMapper;
    }

    @GetMapping("/{keyId}")
    public ResponseEntity<KeyResponseDto> getKeyMetadata(
            @PathVariable String keyId,
            Authentication authentication) {
        VaultKey keyEntity = keyRepository.findByKeyId(keyId)
                .orElseThrow(() -> new IllegalArgumentException("Cryptographic key not found"));
        if (!keyEntity.getTenantId().equals(authentication.getName())) {
            throw new AccessDeniedException("Cannot access cryptographic key belonging to another tenant");
        }
        KeyResponseDto dto = keyMapper.toSafeResponseDto(keyEntity);
        return ResponseEntity.ok(dto);
    }
}
